const chatId = data?.chatId || data?.chat?.id;
const sessionId = data?.sessionId || 'default';
const memoryWindow = parseInt(node.properties.memoryWindow?.value || 10);

helpers.log(`[SQLite Memory] Loading history for chat: ${chatId}, session: ${sessionId}`);

if (!chatId) {
  helpers.warn('No chatId provided - returning empty memory');
  return { messages: [], chatId: null, sessionId };
}

let messages = [];

if (typeof modules?.chatMessages !== 'undefined') {
  try {
    const chatMessages = modules.chatMessages;
    const storedMessages = await chatMessages.getBySession(chatId, sessionId, memoryWindow * 2);

    helpers.log(`Found ${storedMessages.length} stored messages`);

    const recentMessages = storedMessages.slice(-memoryWindow * 2);

    messages = recentMessages
      .filter(msg => msg.role === 'user' || msg.role === 'assistant')
      .map(msg => ({
        role: msg.role,
        content: msg.content,
        timestamp: msg.timestamp
      }));

    helpers.log(`Loaded ${messages.length} messages from SQLite`);
  } catch (e) {
    helpers.error(`SQLite memory load failed: ${e.message}`);
  }
} else {
  helpers.warn('SQLite modules not available');
}

return {
  messages,
  chatId,
  sessionId,
  memoryWindow,
  autoSave: node.properties.autoSave?.value !== false
};
